import React, { useState, useEffect } from 'react';
import {
  Box,
  Typography,
  TextField,
  Button,
  Modal,
  FormControlLabel,
  Checkbox,
  Divider,
  IconButton,
} from '@mui/material';
import { useRecoilValue } from 'recoil';
import { botFlowDataAtom, dynamicWebFormPreviewDataAtom } from '../../../Services/_states';
import SearchableDropdown from '../Common/SearchableDropdown/SearchableDropdown.tsx';
import { FormData, TriggerModalProps } from '../../../interfaces/Flowbuilder.interface.ts';
import { AddCircleOutline, RemoveCircleOutline } from '@mui/icons-material';
import { ConstantActions } from '../../../Services/_actions/constant.actions.js';
import { FlowBuilderActions, TemplateActions } from '../../../Services/_actions/index.js';
import { TemplateFilters, TemplateResponse } from '../../../interfaces/Template.interface.ts';
import { LeadFormActions } from '../../../Services/_actions/index.js';
import CloseIcon from '@mui/icons-material/Close';
import AddIcon from '@mui/icons-material/Add';
import { useSnackBar } from '../Common/SnackBar/index.tsx';

import { useParams } from 'react-router-dom';
import ModalForms from '../../Shared/Modals/index.js';

interface Option {
  label: string;
  value: string;
  key_type?: string;
}

const resultTypeOptions: Option[] = [
  { label: 'Text', value: 'TEXT' },
  { label: 'Image', value: 'IMAGE' },
  { label: 'Video', value: 'VIDEO' },
  { label: 'Audio', value: 'AUDIO' },
  { label: "Date", value: "DATE" },
  { label: "Time", value: "TIME" },
  { label: "Date-time", value: "DATETIME" },
  { label: "File", value: "FILE" },
  { label: "Excel", value: "EXCEL" },
];

const triggerOptions: Option[] = [
  { label: 'From user table', value: 'userTable' },
  { label: 'By Role', value: 'role' },
  { label: 'Manual', value: 'manual' },
];
const outputOptions = [
  { label: 'User Input', value: 'input-value' },
  { label: 'Custom', value: 'custome-value' },
];


const TriggerModal: React.FC<TriggerModalProps> = ({ isOpen, onClose, data }) => {
  const actions = LeadFormActions();
  const { showSnackBar } = useSnackBar();
  const { flowId } = useParams();
  const flowBuilderActions = FlowBuilderActions();
  const constantActions = ConstantActions();
  const templateActions = TemplateActions();
  const [leadFormDataFields, setLeadFormDataFields] = useState([]);
  const webFormList = useRecoilValue(dynamicWebFormPreviewDataAtom);
  const [validationError, setValidationError] = useState({});
  const botFLowData: any = useRecoilValue(botFlowDataAtom);
  const [userList, setUserList] = useState < any > ([]);
  const [roleList, setRoleList] = useState([]);
  const [selectedUserAndRoles, setSelectedUserAndRole] = useState(data?.triggerSettings?.selectedUserAndRoles || []);
  const [phoneNumbers, setPhoneNumbers] = useState < string[] > (data?.triggerSettings?.phoneNumbers || ['']);
  const [triggerText, setTriggerText] = useState < string > (data?.triggerSettings?.triggerText || '');
  const [triggerOption, setTriggerOption] = useState < any > (data?.triggerSettings?.triggerOption || { label: 'Manual', value: 'manual' });
  const [isTriggerEnable, setIsTriggerEnable] = useState < boolean > (data?.triggerSettings?.isTriggerEnable || false);
  const [isStatusEnable, setIsStatusEnable] = useState < boolean > (data?.triggerSettings?.isStatusEnable || false);
  const [responseType, setResponseType] = useState < Option | null > (null);
  const [responseContent, setResponseContent] = useState < string > ('');
  const [selectedField, setSelectedField] = useState < Option | null > (null);
  const [listFilter, setListFilter] = useState({ page: 1, search: "", organisationId: "" });
  const [isLoading, setIsLoading] = useState(false);
  const [hasMore, setHasMore] = useState(true);
  const [templateFilters, setTemplateFilters] = useState < TemplateFilters > ({
    search: '',
    page: 0,
    sortOrder: 'desc',
    sortField: 'created_at',
    category: '',
    botNumber: '',
  });
  const [subBotName, setSubBotName] = useState < string > (data?.triggerSettings?.subBotName || '');
  const [serialNumber, setSerialNumber] = useState < string > (data?.triggerSettings?.serialNumber || '');
  const [selectedTemplate, setSelectedTemplate] = useState(data?.triggerSettings?.selectedTemplate || null);
  const [isTemplateloading, setTemplateIsLoading] = useState(false);
  const [templateList, setTemplateList] = useState < TemplateResponse > ({ pages: 0, list: [{}] });
  const [outputType, setOutputType] = useState(outputOptions[0]); // Default to User Input
  const [customValue, setCustomValue] = useState('');
  const [statusList, setStatusList] = useState < any > ([]);
  const [selectedStatus, setSelectedStatus] = useState(data?.triggerSettings?.selectedStatus || null);
  const [subPatternText, setSubPatternText] = useState(data?.triggerSettings?.sub_pattern?.join(', ') || '');
  const [defaultParams, setDefaultParams] = useState([
    { field: null, value: '' },
  ]);
  const [isSchedulerEnabled, setIsSchedulerEnabled] = useState(data?.triggerSettings?.isSchedulerEnabled || false);
  const [scheduleType, setScheduleType] = useState('');
  const [delay, setDelay] = useState('');
  const [messageType, setMessageType] = useState(data?.triggerSettings?.schedulerSettings?.messageType || '');
  const [messageContent, setMessageContent] = useState < any > (data?.triggerSettings?.schedulerSettings?.messageContent || {});
  const [startDate, setStartDate] = useState(data?.triggerSettings?.schedulerSettings?.startDate || '');
  const [endDate, setEndDate] = useState(data?.triggerSettings?.schedulerSettings?.endDate || '');
  const [time, setTime] = useState(data?.triggerSettings?.schedulerSettings?.time || '');

  const modifyWebFormListObj = (obj: any) => {
    try {
      if (!obj || Object.keys(obj).length === 0) {
        return [];
      }
      return Object.values(obj);
    } catch (error) {
      console.warn(error);
      return [];
    }
  };
  useEffect(() => {
    if (!webFormList || !botFLowData?.campaign_id || !botFLowData?.lead_form_id) {
      return;
    }
    const fields = modifyWebFormListObj(webFormList?.[botFLowData.campaign_id]?.[botFLowData.lead_form_id]?.leads_form_items)
    setLeadFormDataFields(fields);
  }, [webFormList, botFLowData?.campaign_id, botFLowData?.lead_form_id]);


  const validateForm = () => {
    let errors: any = {};
    if (isTriggerEnable) {
      if (triggerOption?.value === "manual") {
        if (phoneNumbers.length === 0) {
          errors.phoneNumber = "Add atleast one phone number";
        } else {
          phoneNumbers.forEach((num: string, index: number) => {
            if (!validatePhoneNumber(num)) {
              errors[`phoneNumbers${index}`] = "Enter valid phone number with country code";
            }
          })
        }
      };
    }

    if (isSchedulerEnabled) {
      if (!scheduleType) {
        errors.scheduleType = 'Schedule type is required';
      }

      if ((scheduleType === 'X minutes later' || scheduleType === 'X hours later') && !delay) {
        errors.delay = 'Delay is required';
      }

      if ((scheduleType === 'Once' || scheduleType === 'Custom') && (!startDate || !endDate || !time)) {
        errors.scheduleDates = 'Start, End Date and Time are required';
      }

      if (!messageType) {
        errors.messageType = 'Message type is required';
      }

      if (messageType === 'text' && !messageContent?.body?.text) {
        errors.messageContent = 'Text body is required';
      }
    }


    defaultParams.forEach((param, index) => {
      const hasField = !!param.field;
      const hasValue = !!param.value?.trim();

      if ((hasField && !hasValue) || (!hasField && hasValue)) {
        errors[`defaultParams-${index}`] = "Both field and value are required";
      }
    });

    setValidationError(errors);
    return errors;

  }
  const removeParamType = (obj: Option) => {
    try {
      return {
        ...obj,
        label: obj.label.replace(/^(webform__|result__)/, ''), // Remove "webform__" or "result__"
        value: obj.value.replace(/^(webform__|result__)/, '')  // Remove "webform__" or "result__"
      };
    } catch (error) {
      return obj;
    }
  }


  const getTemplateList = async (data) => {
    setTemplateIsLoading(true);
    setTemplateFilters({ ...data });
    try {
      const res = await templateActions.getWhatsappTemplateList(data);
      setTemplateList(res);
    } catch (error) {
      console.error('Error fetching template list:', error);
    } finally {
      setTemplateIsLoading(false);
    }
  };

  const handleSearchTemplate = (query: string) => {
    getTemplateList({ ...templateFilters, search: query || '' });
  };

  const loadMoreTemplates = async () => {
    if (templateFilters?.page < templateList?.pages) {
      setTemplateIsLoading(true);
      let listData = Array.isArray(templateList?.list) ? [...templateList?.list] : [];
      const data = { ...templateFilters, search: '', page: templateFilters.page + 1 };
      setTemplateFilters(data);

      try {
        const res = await templateActions.getWhatsappTemplateList(data);
        if (Array.isArray(res?.list)) {
          listData = [...listData, ...res.list];
          setTemplateList({ ...res, list: listData });
        } else {
          console.warn('Received non-array response for Template list');
        }
      } catch (error) {
        console.error('Error loading more templates:', error);
      } finally {
        setTemplateIsLoading(false);
      }
    }
  };



  const handleSave = async () => {
    const errors = validateForm();
    if (Object.keys(errors).length > 0)
      return;
    let settings = {};
    const isFieldMatched = resultTypeOptions.some((field) => field.value === selectedField?.key_type);
    const transformedDefaultParams = defaultParams
      .filter(param => param.field && param.value)
      .map(param => ({
        key_name: param.field?.value || '',
        value: param.value
      }));

    if (leadFormDataFields.length > 0) {
      settings = {
        triggerText,
        triggerOption,
        isTriggerEnable,
        selectedUserAndRoles,
        selectedTemplate,
        phoneNumbers,
        isStatusEnable,
        selectedStatus,
        sub_pattern: subPatternText.split(',').map(k => k.trim().toLowerCase()).filter(k => k !== ''),
        result: {
          type: isFieldMatched ? responseType?.value : 'TEXT',
          label: selectedField?.value ? `webform__${selectedField?.value}` : '',
          value: selectedField?.value ? `webform__${selectedField?.value}` : '',
          // label: selectedField?.label ?? '',
          // value: selectedField?.value ? `webform__${selectedField?.value}` : '',
          paramType: selectedField?.value ? 'webform' : '',
          output_result: outputType?.value,
          custom_value: outputType?.value === 'custome-value' ? customValue : '',
          node_id: data?.id ?? null,
        },
        subBotName,
        schedulerSettings: isSchedulerEnabled
          ? {
            scheduleType,
            delay,
            startDate,
            endDate,
            time,
            node_type: messageType === 'button' ? 'BUTTONS' : messageType,
            message: messageType === 'text'
              ? {
                body: {
                  type: 'TEXT',
                  text: messageContent?.body?.text || ''
                }
              }
              : messageContent
          }
          : {},
        isSchedulerEnabled,
        serialNumber,
        default_params: transformedDefaultParams,

      };
    } else {
      settings = {
        triggerText,
        triggerOption,
        isTriggerEnable,
        selectedUserAndRoles,
        selectedTemplate,
        phoneNumbers,
        isStatusEnable,
        selectedStatus,
        sub_pattern: subPatternText.split(',').map(k => k.trim().toLowerCase()).filter(k => k !== ''),
        result: {
          type: responseType?.value,
          label: `result__${responseContent.trim().toLowerCase().replace(/\s+/g, '_')}`,
          value: `result__${responseContent.trim().toLowerCase().replace(/\s+/g, '_')}`,
          paramType: 'result',
          output_result: outputType?.value,
          custom_value: outputType?.value === 'custome-value' ? customValue : '',
          node_id: data?.id ?? null
        },
        subBotName,
        schedulerSettings: isSchedulerEnabled
          ? {
            scheduleType,
            delay,
            startDate,
            endDate,
            time,
            node_type: messageType === 'button' ? 'BUTTONS' : messageType,
            message: messageType === 'text'
              ? {
                body: {
                  type: 'TEXT',
                  text: messageContent?.body?.text || ''
                }
              }
              : messageContent
          }
          : {},
        isSchedulerEnabled,
        serialNumber,
        default_params: transformedDefaultParams,
      };
    }
    if (isSchedulerEnabled) {
      const payload = {
        ...settings.schedulerSettings,
        flow_id: flowId || '',

        bot_number: botFLowData?.phone_number_id,
        company_id: botFLowData?.company_id,
        message: settings?.schedulerSettings?.message ?? {},
        created_at: new Date()?.toISOString(),
        created_by: botFLowData?.created_by || 'system', // Adjust based on your context
      };

      try {
        const res = await flowBuilderActions.scheduleBot.post(payload);
        if (res?.status === 200 || res?.status === 201) {
          showSnackBar("Scheduled message created successfully!", "success");
          if (typeof data?.onSchedulerSave === 'function') {
            data.onSchedulerSave();
          }

        } else {
          showSnackBar("Failed to create scheduled message", "error");

        }
      } catch (err) {
        console.error("Schedule API error in TriggerModal:", err);
      }
    }
    data?.onChange(data.id, { triggerSettings: settings });
    onClose();
  };

  const onSelectFormField = (item: Option) => {
    setSelectedField(item);
    const obj = resultTypeOptions.find((opt) => opt.value === item?.key_type);
    setResponseType(obj || { label: 'Text', value: 'TEXT' });
  };

  const removePhoneNumber = (index: number) => {
    const newPhoneNumbers = phoneNumbers.filter((_, i) => i !== index);
    setPhoneNumbers(newPhoneNumbers);
  };
  const handlePhoneNumberChange = (index: number, value: string) => {
    const newPhoneNumbers = [...phoneNumbers];
    newPhoneNumbers[index] = value;
    setPhoneNumbers(newPhoneNumbers);
    let error = { ...validationError };
    delete error[`phoneNumbers${index}`];
    setValidationError(error);
  };
  // const validatePhoneNumber = (phone: string) => {
  //   const phoneRegex = /^\+([1-9]{1}[0-9]{1,14})$/;
  //   return phoneRegex.test(phone);
  // };
  const validatePhoneNumber = (phone: string) => {
    const phoneRegex = /^([1-9]{1}[0-9]{1,14})$/;
    return phoneRegex.test(phone);
  };

  const handleTriggerOptionChange = async (item: Option) => {
    setSelectedUserAndRole([]);
    setPhoneNumbers([]);
    if (item?.value === "role") {
      let res = await constantActions.getKeyStakeholdersByOrganisation(listFilter?.organisationId);
      let roleListWithLabelValue = res?.map(role => ({
        ...role,
        label: role?.name,
        value: role?.id
      }));
      setRoleList(roleListWithLabelValue);
    } else if (item?.value === "userTable") {
      let res = await constantActions.getUsersByOrganisation({ ...listFilter, page: 1 });
      let userListWithLabelValue = (res?.list || [])?.map(user => ({
        ...user,
        label: user?.username,
        value: user?.id
      }));
      setListFilter({ ...listFilter, page: 2 });
      setUserList(userListWithLabelValue || []);
    }
    setTriggerOption(item || null)
  };

  const loadUser = async () => {
    if (isLoading || !hasMore) return;
    setIsLoading(true);
    const res = await constantActions.getUsersByOrganisation(listFilter);
    const newUsers = (res?.list || [])?.map(user => ({
      ...user,
      label: user?.username,
      value: user?.id
    }));
    setUserList((prevList) => [...prevList, ...newUsers]);
    setHasMore(res?.has_next);
    setListFilter((prev) => ({
      ...prev,
      page: prev.page + 1,
    }));
    setIsLoading(false);
  };

  const allMessageTypeOptions = [
    { label: 'Text', value: 'text' },
    // { label: 'Image', value: 'image' },
    // { label: 'Video', value: 'video' },
    // { label: 'Document', value: 'document' },
    // { label: 'Audio', value: 'audio' },
    { label: 'Button', value: 'button' },
    // { label: 'List', value: 'list' },
  ];

  const getStatusList = async () => {
    setIsLoading(true);
    try {
      if (statusList?.length > 0) return;
      const res = await actions.fetchStatusAndSubStatus({
        leadFormId: data?.leadFormId || botFLowData?.leadFormId || botFLowData?.lead_form_id || '',
        active: true,
      });

      if (res?.status === 200) {
        const allStatuses = res?.data || [];
        const activeStatuses = allStatuses.filter(item => item?.active === true);
        setStatusList(activeStatuses);
      }
    } catch (error) {
      console.warn('Error fetching status/substatus:', error);
    } finally {
      setIsLoading(false);
    }
  };



  useEffect(() => {
    if (botFLowData?.company_id)
      setListFilter({ ...listFilter, organisationId: botFLowData?.company_id });
  }, [botFLowData]);

  useEffect(() => {
    if (botFLowData?.phone_number_id && isOpen)
      getTemplateList({ ...templateFilters, botNumber: botFLowData?.phone_number_id });
  }, [isOpen]);

  useEffect(() => {
    if (leadFormDataFields.length > 0) {
      const updatedObj = removeParamType(data?.triggerSettings?.result);
      setSelectedField(updatedObj);
    } else if (data?.triggerSettings?.result?.label) {
      let result = removeParamType(data?.triggerSettings?.result);
      setResponseContent(result?.label ?? '')
    }
  }, [leadFormDataFields]);

  useEffect(() => {
    const initialResultType = resultTypeOptions.find((opt) => opt.value === data?.triggerSettings?.result?.type);
    setResponseType(initialResultType || { label: 'Text', value: 'TEXT' });
    if (data?.triggerSettings?.result?.output_result === "custome-value") {
      setOutputType(outputOptions[1]);
      setCustomValue(data?.triggerSettings?.result?.custom_value || '')
    }
  }, [data]);

  useEffect(() => {
    if (data?.triggerSettings?.default_params?.length > 0 && leadFormDataFields.length > 0) {
      const populatedParams = data.triggerSettings.default_params.map(param => {
        const matchingField = leadFormDataFields.find(
          f => f.key_name === param.key_name
        );
        return {
          field: matchingField
            ? {
              ...matchingField,
              label: matchingField.key_name,
              value: matchingField.key_name,
            }
            : null,
          value: param.value,
        };
      });

      setDefaultParams(populatedParams);
    }
  }, [data?.triggerSettings?.default_params, leadFormDataFields]);

  useEffect(() => {
    if (data?.triggerSettings?.isStatusEnable) {
      getStatusList();
    }
  }, []);

  const getSelectedField = (field: any) => {
    try {
      if (field?.value) {
        const obj = leadFormDataFields?.find((item: any) => item?.key_name === field?.value);
        return { ...obj, label: obj?.key_name }
      } else {
        return null;
      }
    } catch {
      return null;
    }
  }

  return (
    // <Modal open={isOpen} onClose={onClose}>

    // </Modal>
    <ModalForms
      show={isOpen}
      handleClose={onClose}
      modalHeader={"Configure Intent"}

      modalBody={<>
        <Box
        // sx={{
        //   position: 'absolute',
        //   top: '50%',
        //   left: '50%',
        //   transform: 'translate(-50%, -50%)',
        //   bgcolor: 'background.paper',
        //   boxShadow: 24,
        //   borderRadius: '8px',
        //   p: 3,
        //   width: 437,
        //   maxHeight: '90vh',
        //   overflowY: 'auto',
        // }}
        >
          {/* <Typography variant="h6" fontWeight="bold" gutterBottom>
            Conigfure Intent
          </Typography> */}

          {/* Sub Bot Name */}
          <TextField fullWidth size="small" label="Sub Bot Name" value={subBotName} onChange={(e) => setSubBotName(e.target.value)} margin="dense" variant="outlined" sx={{ mb: 2 }} />

          {/* Serial Number */}
          <TextField fullWidth size="small" label="Serial Number" value={serialNumber} onChange={(e) => setSerialNumber(e.target.value)} margin="dense" variant="outlined" sx={{ mb: 2 }} />
          <TextField
            fullWidth
            size="small"
            label="Sub Keywords (comma-separated)"
            value={subPatternText}
            onChange={(e) => {
              let cleaned = e.target.value.replace(/\s*,\s*/g, ', ').replace(/\s+/g, ' ');
              setSubPatternText(cleaned);
            }}
            placeholder="e.g. keyword1, keyword2"
            margin="dense"
            variant="outlined"
            sx={{ marginBottom: 2 }}
          />

          <Box mt={3}>
            <Typography variant="subtitle2" gutterBottom>
              Result Settings
            </Typography>
            <Divider sx={{ mb: 2 }} />
            {leadFormDataFields.length > 0 ? (
              <SearchableDropdown
                label={<Typography component="span">Result Name</Typography>}
                options={leadFormDataFields
                  .filter((item: any) =>
                    !['lead_id', 'order_id'].includes(item?.key_name?.toLowerCase())
                  )
                  .map((item: any) => ({
                    ...item,
                    label: item?.key_name || '',
                    value: item?.key_name || '',
                  }))}
                value={getSelectedField(selectedField)}
                onChange={(value: Option) => onSelectFormField(value)}
                sx={{ marginBottom: 2 }}
              />
            ) : (
              <TextField
                fullWidth
                size="small"
                label="Result name"
                value={responseContent}
                onChange={(e) => setResponseContent(e.target.value)}
                placeholder="Enter response content"
                margin="dense"
                variant="outlined"
                sx={{ marginBottom: 2 }}
              />
            )}
            <SearchableDropdown
              label="Response Type"
              options={resultTypeOptions}
              value={responseType || null}
              onChange={(value: Option) => setResponseType(value)}
              disabled={leadFormDataFields.length > 0}
              sx={{ marginBottom: 2 }}
            />
            <SearchableDropdown
              label="Output"
              options={outputOptions}
              value={outputType}
              onChange={(value) => setOutputType(value)}
            />

            {outputType?.value === 'custome-value' && (
              <TextField
                fullWidth
                size="small"
                label="Custom Value"
                value={customValue}
                onChange={(e) => setCustomValue(e.target.value)}
                placeholder="Enter custom value"
                margin="dense"
                variant="outlined"
                sx={{ marginBottom: 2 }}
                multiline
                maxRows={4}
              />
            )}
          </Box>


          <Box mt={1}>
            <Typography variant="subtitle2" gutterBottom>
              Trigger Settings
            </Typography>
            <Divider sx={{ mb: 2 }} />
            <FormControlLabel
              control={
                <Checkbox
                  checked={isSchedulerEnabled}
                  onChange={(e) => setIsSchedulerEnabled(e.target.checked)}
                />
              }
              label="Enable Scheduler"
              sx={{ mb: 1 }}
            />
            {isSchedulerEnabled && (
              <>
                <SearchableDropdown
                  label="Schedule Type"
                  options={[
                    { label: 'Once', value: 'Once' },
                    { label: 'Daily', value: 'Daily' },
                    { label: 'Weekly', value: 'Weekly' },
                    { label: 'Yearly', value: 'Yearly' },
                    { label: 'X minutes later', value: 'X minutes later' },
                    { label: 'X hours later', value: 'X hours later' },
                    { label: 'Custom', value: 'Custom' },
                  ]}
                  value={scheduleType ? { label: scheduleType, value: scheduleType } : null}
                  onChange={(val) => setScheduleType(val?.value)}
                  sx={{ mb: 1 }}
                />

                {(scheduleType === 'X minutes later' || scheduleType === 'X hours later') && (
                  <TextField
                    fullWidth
                    size="small"
                    label={`Delay (${scheduleType.includes('minutes') ? 'Minutes' : 'Hours'})`}
                    value={delay}
                    onChange={(e) => setDelay(e.target.value)}
                    type="number"
                    sx={{ mb: 1 }}
                  />
                )}

                {(scheduleType === 'Once' || scheduleType === 'Custom') && (
                  <>
                    <TextField
                      fullWidth
                      size="small"
                      type="date"
                      label="Start Date"
                      value={startDate}
                      onChange={(e) => setStartDate(e.target.value)}
                      InputLabelProps={{ shrink: true }}
                      sx={{ mb: 1 }}
                    />
                    <TextField
                      fullWidth
                      size="small"
                      type="date"
                      label="End Date"
                      value={endDate}
                      onChange={(e) => setEndDate(e.target.value)}
                      InputLabelProps={{ shrink: true }}
                      sx={{ mb: 1 }}
                    />
                    <TextField
                      fullWidth
                      size="small"
                      type="time"
                      label="Time"
                      value={time}
                      onChange={(e) => setTime(e.target.value)}
                      InputLabelProps={{ shrink: true }}
                      sx={{ mb: 1 }}
                    />
                  </>
                )}

                {/* Optional: Message Type */}
                <SearchableDropdown
                  label="Message Type"
                  options={allMessageTypeOptions}
                  value={allMessageTypeOptions.find(opt => opt.value === messageType) || null}
                  onChange={(val) => {
                    setMessageType(val?.value || '');
                    setMessageContent({});
                  }}
                  sx={{ mb: 1 }}
                />
                {isSchedulerEnabled && messageType && (
                  <>
                    {messageType === 'text' && (
                      <TextField
                        fullWidth
                        size="small"
                        label="Body Text"
                        value={messageContent?.body?.text || ''}
                        onChange={(e) =>
                          setMessageContent({
                            body: {
                              type: 'TEXT',
                              text: e.target.value
                            }
                          })
                        }
                        sx={{ mb: 1 }}
                        multiline
                        maxRows={4}
                      />
                    )}

                    {messageType === 'button' && (
                      <>
                        <TextField
                          fullWidth
                          size="small"
                          label="Button Header"
                          value={messageContent?.header?.text || ''}
                          onChange={(e) =>
                            setMessageContent((prev) => ({
                              ...prev,
                              header: { text: e.target.value, type: 'TEXT' }
                            }))
                          }
                          sx={{ mb: 1 }}
                        />

                        <TextField
                          fullWidth
                          size="small"
                          label="Button Body"
                          value={messageContent?.body?.text || ''}
                          onChange={(e) =>
                            setMessageContent((prev) => ({
                              ...prev,
                              body: { text: e.target.value, type: 'TEXT' }
                            }))
                          }
                          sx={{ mb: 1 }}
                        />

                        <TextField
                          fullWidth
                          size="small"
                          label="Button Footer"
                          value={messageContent?.footer?.text || ''}
                          onChange={(e) =>
                            setMessageContent((prev) => ({
                              ...prev,
                              footer: { text: e.target.value, type: 'TEXT' }
                            }))
                          }
                          sx={{ mb: 1 }}
                        />

                        <Box sx={{ mb: 2 }}>
                          <Typography variant="subtitle2" gutterBottom>
                            Buttons
                          </Typography>
                          {messageContent?.buttons?.map((btn, idx) => (
                            <Box key={idx} sx={{ display: 'flex', alignItems: 'center', gap: 1, mb: 1 }}>
                              <TextField
                                fullWidth
                                size="small"
                                label={`Button ${idx + 1} Label`}
                                value={btn?.label || ''}
                                onChange={(e) => {
                                  const newButtons = [...(messageContent?.buttons || [])];
                                  newButtons[idx] = { ...newButtons[idx], label: e.target.value };
                                  setMessageContent((prev) => ({ ...prev, buttons: newButtons }));
                                }}
                                sx={{ mb: 1 }}
                              />
                              <IconButton
                                onClick={() => {
                                  const newButtons = messageContent?.buttons.filter((_, i) => i !== idx);
                                  setMessageContent((prev) => ({ ...prev, buttons: newButtons }));
                                }}
                                size="small"
                              >
                                <CloseIcon />
                              </IconButton>
                            </Box>
                          ))}

                          <Button
                            size="small"
                            variant="outlined"
                            onClick={() => {
                              const newButtons = [...(messageContent?.buttons || []), { label: '', action: {} }];
                              setMessageContent((prev) => ({ ...prev, buttons: newButtons }));
                            }}
                          >
                            + Add Button
                          </Button>
                        </Box>
                      </>
                    )}
                  </>
                )}

              </>
            )}

            <Divider sx={{ mb: 2 }} />
            <FormControlLabel
              control={
                <Checkbox
                  checked={isTriggerEnable}
                  onChange={(e) => setIsTriggerEnable(e.target.checked)}
                />
              }
              label="Enable Trigger"
              sx={{ mb: 1 }}
            />

            <SearchableDropdown
              label="Template"
              options={templateList?.list}
              value={selectedTemplate || null}
              onSearch={handleSearchTemplate}
              onChange={(value) => setSelectedTemplate(value)}
              getOptionLabel={(option) => option?.name}
              fetchMoreOptions={templateList?.has_next ? loadMoreTemplates : undefined}
              loading={isTemplateloading}
              sx={{ marginBottom: 1 }}
            />

            {isTriggerEnable && (
              <>
                <SearchableDropdown
                  label="Trigger Option"
                  options={triggerOptions}
                  value={triggerOption}
                  onChange={handleTriggerOptionChange}
                  sx={{ mb: 0.5 }}
                />
                {triggerOption?.value === 'userTable' ? (
                  <SearchableDropdown
                    label="Select Users"
                    options={userList} // Add actual options for users/roles here
                    value={selectedUserAndRoles || []} // The selected value will be managed here
                    onChange={(e: any) => setSelectedUserAndRole(e)}
                    multiSelect={true}
                    sx={{ mb: 1 }}
                    fetchMoreOptions={loadUser}
                    loading={isLoading}
                    getOptionDisabled={(option: any) => !option?.mobile}
                  // getOptionLabel={(option) => option?.username}
                  // fetchMoreOptions={userList?.has_next ? loadUser : undefined} 
                  />
                ) : triggerOption?.value === "role" ?
                  (
                    <SearchableDropdown
                      label="Select Roles"
                      multiSelect={true}
                      options={roleList} // Add actual options for users/roles here
                      value={selectedUserAndRoles || []} // The selected value will be managed here
                      onChange={(value: any) => setSelectedUserAndRole(value)}
                      // getOptionLabel={(option) => option?.name}
                      sx={{ mb: 1 }}
                    />
                  )
                  : triggerOption?.value === "manual" ? (
                    <>
                      <Typography variant="subtitle2">
                        Add Phone Numbers
                      </Typography>
                      {phoneNumbers?.map((phone, index) => (
                        <Box key={index} display="flex" alignItems="center" gap={1} mb={1}>
                          <TextField
                            fullWidth
                            size="small"
                            label={`Phone Number ${index + 1}`}
                            value={phone}
                            onChange={(e) => handlePhoneNumberChange(index, e.target.value)}
                            placeholder="Enter phone number with country code"
                            margin="dense"
                            variant="outlined"
                            error={!validatePhoneNumber(phone)}
                            helperText={phone && !validatePhoneNumber(phone) ? "Enter valid phone number with country code" : ''}
                          />
                          {phoneNumbers.length > 1 && (
                            <RemoveCircleOutline
                              onClick={() => removePhoneNumber(index)}
                              sx={{ cursor: 'pointer', color: 'error.main' }}
                            />
                          )}
                        </Box>
                      ))}
                      <Typography
                        variant="body2"
                        style={{
                          marginTop: '10px',
                          cursor: 'pointer',
                          color: '#007bff',
                          textDecoration: 'underline',
                          fontSize: '14px',
                        }}
                        onClick={() => setPhoneNumbers((prev) => [...prev, ''])}
                      >
                        + Add More
                      </Typography>
                    </>
                  ) : null
                }
              </>
            )}
            <FormControlLabel
              control={
                <Checkbox
                  checked={isStatusEnable}
                  onChange={(e) => { setIsStatusEnable(e.target.checked); e.target.checked ? getStatusList() : null }}
                />
              }
              label="Enable Status"
              sx={{ mb: 1 }}
            />
            {isStatusEnable &&
              <SearchableDropdown
                label={"Select Status"}
                options={statusList}
                labelKey='status_name'
                valueKey='status_id'
                value={statusList?.find((status) => status?.status_id === selectedStatus?.status_id) ?? null}
                onChange={(value) => {
                  setSelectedStatus({ status_id: value?.status_id ?? "", status_name: value?.status_name ?? "" })
                }}
              />
            }

          </Box>
          <Box mt={1}>
            <Typography variant="subtitle2" gutterBottom>
              Default Parameters
            </Typography>
            <Divider sx={{ mb: 2 }} />
            <Box
              sx={{
                maxHeight: 200,
                overflowY: 'auto',
                pr: 1,
              }}
            >
              {defaultParams.map((param, index) => {
                const errorKey = `defaultParams-${index}`;
                const errorMessage = validationError[errorKey];
                return (
                  <Box key={index} display="flex" alignItems="center" gap={1} sx={{ mb: 2 }}>
                    <SearchableDropdown
                      label={<Typography component="span">Key Name</Typography>}
                      options={leadFormDataFields
                        .filter((item: any) =>
                          !['lead_id', 'order_id'].includes(item?.key_name?.toLowerCase())
                        )
                        .map((item: any) => ({
                          ...item,
                          label: item?.key_name || '',
                          value: item?.key_name || '',
                        }))}
                      value={param.field}
                      onChange={(value: Option) => {
                        const updatedParams = [...defaultParams];
                        updatedParams[index].field = value;
                        setDefaultParams(updatedParams);
                        const newErrors = { ...validationError };
                        delete newErrors[errorKey];
                        setValidationError(newErrors);
                      }}
                      error={!!errorMessage}
                    />

                    <TextField
                      fullWidth
                      size="small"
                      label="Value"
                      value={param.value}
                      onChange={(e) => {
                        const updatedParams = [...defaultParams];
                        updatedParams[index].value = e.target.value;
                        setDefaultParams(updatedParams);

                        // ✅ clear error for this field
                        const newErrors = { ...validationError };
                        delete newErrors[errorKey];
                        setValidationError(newErrors);
                      }}
                      placeholder="Value"
                      margin="dense"
                      variant="outlined"
                      error={!!errorMessage}
                      helperText={errorMessage}
                    />

                    {index === defaultParams.length - 1 ? (
                      <IconButton
                        aria-label="add"
                        onClick={() => setDefaultParams([...defaultParams, { field: null, value: '' }])}
                      >
                        <AddIcon />
                      </IconButton>
                    ) : null}

                    {index !== 0 && (
                      <IconButton
                        aria-label="remove"
                        onClick={() => {
                          const updatedParams = defaultParams.filter((_, i) => i !== index);
                          setDefaultParams(updatedParams);
                          const newErrors = { ...validationError };
                          delete newErrors[errorKey];
                          setValidationError(newErrors);
                        }}
                      >
                        <CloseIcon />
                      </IconButton>
                    )}
                  </Box>
                );
              })}

            </Box>
          </Box>
        </Box>
      </>}
      modalFooter={<Box mt={3} display="flex" justifyContent="flex-end" gap={2}>
        <Button variant="outlined" onClick={onClose} size="small">
          Cancel
        </Button>
        <Button
          variant="contained"
          color="primary"
          onClick={handleSave}
          disableElevation
          size="small"
        >
          Save
        </Button>
      </Box>}

    />
  );
};

export default TriggerModal;
